import {String} from '../constants';
import {getConfig} from './httpClient';

export const createAccountInfoServices = (fetchRequest: any) => ({
  async deleteAvatar() {
    try {
      const endpoint = '/services/uaa/api/account/avatar';
      const data = await fetchRequest({
        url: getConfig().BASE_URL_EACCOUNT + endpoint,
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        typeOfResponse: '',
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('deleteAvatar: ', error);
      return Promise.reject(error);
    }
  },

  async updateAccountAvatar(body: FormData) {
    try {
      const endpoint = '/services/uaa/api/account/avatar-zoom';
      const data = await fetchRequest({
        url: getConfig().BASE_URL_EACCOUNT + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'multipart/form-data',
        },
        body,
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('updateAccountAvatar: ', error);
      return Promise.reject(error);
    }
  },

  async updateAccount(body: any) {
    try {
      const endpoint = '/services/uaa/api/account';
      const data = await fetchRequest({
        url: getConfig().BASE_URL_EACCOUNT + endpoint,
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('updateAccount: ', error);
      return Promise.reject(error);
    }
  },

  async getSecuriryPasswordRules(): Promise<any> {
    try {
      const endpoint = '/services/uaa/api/security-configs/all';
      const data = await fetchRequest({
        url: getConfig().BASE_URL_EACCOUNT + endpoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('getSecuriryPasswordRules: ', error);
      return Promise.reject(error);
    }
  },

  async changePassword(body: any): Promise<any> {
    try {
      const endpoint = '/services/uaa/api/account/change-password';
      const data = await fetchRequest({
        url: getConfig().BASE_URL_EACCOUNT + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
        getValueErr: true,
        typeOfResponse: '',
      });
      return Promise.resolve(data);
    } catch (error: any) {
      console.error('changePassword: ', error);
      return Promise.reject(error);
    }
  },

  async getOrganizationDetail() {
    try {
      const endpoint = '/services/uaa/api/organization-detail-profile';
      const data = await fetchRequest({
        url: getConfig().BASE_URL_EACCOUNT + endpoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('getOrganizationDetail: ', error);
      return Promise.reject(error);
    }
  },

  async getOrgLegalInProfileAuth(step: string) {
    try {
      const endpoint = `/services/uaa/api/profile-authentication/legal?step=${step}`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL_EACCOUNT + endpoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('getOrgLegalInProfileAuth: ', error);
      return Promise.reject(error);
    }
  },

  async getPersonalProfileEkyc(userId: any) {
    try {
      const endpoint =
        '/services/uaa/api/personal-kyc-detail-profiles-eaccount-by-userId/' +
        userId;
      const data = await fetchRequest({
        url: getConfig().BASE_URL_EACCOUNT + endpoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('getPersonalProfileEkyc: ', error);
      return Promise.reject(error);
    }
  },

  async getMenuView() {
    const endpoint = '/services/uaa/api/menu-swaps';
    const data = await fetchRequest({
      url: getConfig().BASE_URL_EACCOUNT + endpoint,
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
    });
    return Promise.resolve(data?.data);
  },

  async blockUser(body: any) {
    try {
      const endpoint = `/services/uaa/api/users-block`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL_EACCOUNT + endpoint,
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      console.error('blockUser: ', error);
      return Promise.reject(error);
    }
  },
  async fetchLocation(params: any) {
    try {
      const url = `${String.NOMINATIM_HOST}?lat=${params.lat}&lon=${params.lon}&format=json`;
      const dataLocation = await fetchRequest({
        url,
        method: 'GET',
      });
      return Promise.resolve(dataLocation?.data);
    } catch (error) {
      console.error('Error fetching location:', error);
      throw error;
    }
  },
  async loginMiniApp() {
    const endPoint = '/auth/login';
    try {
      const data = await fetch(getConfig().BASE_URL_EACCOUNT + endPoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          // username: 'econcadastest@gmail.com',
          username: 'thads@yopmail.com',
          password: 'admin@123',
        }),
      });
      return Promise.resolve(data.json());
    } catch (error) {
      return Promise.reject(error);
    }
  },

  async getListAccount(dataFilter?: any, params?: any) {
    let body = {
      advanced: false,
      contactId: '',
      custId: null,
      logins: [],
      field: '',
      from: '',
      keyWord: '',
      orgIn: null,
      owner: '',
      q: '',
      recipientId: '',
      recipientRole: [],
      refId: '',
      resource: 'table_user',
      terms: {},
      to: '',
    };
    if (dataFilter) {
      body = {
        ...body,
        ...dataFilter,
      };
    }
    const endPoint = '/services/uaa/api/search/user-info/role';
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL_EACCOUNT + endPoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
        params: params,
      });
      return Promise.resolve({
        data: data?.data,
        totalRecords: Number(data?.headers.get('x-total-count')),
      });
    } catch (error) {
      Promise.reject(error);
    }
  },
});
